<div class="d-flex justify-content-between mb-3"><h1 class="h3">Products</h1><a class="btn btn-primary" href="<?= site_url('products/new') ?>">+ Add Product</a></div><div class="card shadow-sm"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Image</th><th>Name</th><th>Price</th><th>Stock</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?php if($p['image']): ?><img class="thumb" src="<?= base_url('uploads/products/'.$p['image']) ?>" alt=""><?php else: ?><span class="placeholder-img">No image</span><?php endif ?></td><td class="fw-semibold"><?= esc($p['name']) ?></td><td>₱<?= number_format($p['price'],2) ?></td><td><span class="badge <?= $p['stock_quantity']<5?'text-bg-danger':'text-bg-success' ?>"><?= $p['stock_quantity'] ?></span></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="<?= site_url('products/'.$p['id'].'/edit') ?>">Edit</a><?= form_open('products/'.$p['id'],['class'=>'d-inline','onsubmit'=>"return confirm('Delete this product?')"]) ?><input type="hidden" name="_method" value="DELETE"><button class="btn btn-sm btn-outline-danger">Delete</button><?= form_close() ?></td></tr><?php endforeach ?><?php if(!$products): ?><tr><td colspan="5" class="text-center text-secondary py-4">No products yet.</td></tr><?php endif ?></tbody></table></div></div>
